#include <cctype>
#include <map>
#include <sstream>
#include <string>
#include <vector>

struct DriverVer { int month, day, year; int v[4]; };
struct VersionInfo { std::string signature, cls, provider, catalog; DriverVer ver; };

namespace
{
    std::string trim(const std::string& s)
    {
        const auto b{ s.find_first_not_of(" \t") };
        if (b == std::string::npos) return "";
        return s.substr(b, s.find_last_not_of(" \t") - b + 1);
    }
    std::string lower(std::string s) { for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c))); return s; }

    bool number(const std::string& s, int maxDigits, int& out)
    {
        if (s.empty() || static_cast<int>(s.size()) > maxDigits) return false;
        for (char c : s) if (!std::isdigit(static_cast<unsigned char>(c))) return false;
        out = std::stoi(s);
        return true;
    }

    std::vector<std::string> split(const std::string& s, char sep)
    {
        std::vector<std::string> parts;
        std::string part;
        for (char c : s) { if (c == sep) { parts.push_back(part); part.clear(); } else part += c; }
        parts.push_back(part);
        return parts;
    }
}

bool parseDriverVer(const std::string& text, DriverVer& out)
{
    const auto comma{ text.find(',') };
    if (comma == std::string::npos) return false;
    const auto date{ split(text.substr(0, comma), '/') };
    const auto ver{ split(text.substr(comma + 1), '.') };
    DriverVer d{ 0, 0, 0, { 0, 0, 0, 0 } };
    if (date.size() != 3 || !number(date[0], 2, d.month) || !number(date[1], 2, d.day) || !number(date[2], 4, d.year)) return false;
    if (d.month < 1 || d.month > 12 || d.year < 1900) return false;
    const bool leap{ (d.year % 4 == 0 && d.year % 100 != 0) || d.year % 400 == 0 };
    const int days[]{ 31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    if (d.day < 1 || d.day > days[d.month - 1]) return false;
    if (ver.empty() || ver.size() > 4) return false;
    for (std::size_t i{ 0 }; i < ver.size(); ++i) if (!number(ver[i], 5, d.v[i]) || d.v[i] > 65535) return false;
    out = d;
    return true;
}

std::vector<std::string> checkVersion(const std::string& inf, VersionInfo& out)
{
    std::map<std::string, std::string> values;
    bool inVersion{ false }, sawVersion{ false };
    std::istringstream in{ inf };
    for (std::string line; std::getline(in, line);)
    {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        const auto semi{ line.find(';') };
        if (semi != std::string::npos) line = line.substr(0, semi);
        line = trim(line);
        if (line.empty()) continue;
        if (line.front() == '[' && line.back() == ']')
        {
            inVersion = lower(trim(line.substr(1, line.size() - 2))) == "version";
            sawVersion = sawVersion || inVersion;
            continue;
        }
        if (!inVersion) continue;
        const auto eq{ line.find('=') };
        if (eq == std::string::npos) continue;
        values[lower(trim(line.substr(0, eq)))] = trim(line.substr(eq + 1));
    }
    std::vector<std::string> problems;
    if (!sawVersion) return { "no [Version] section" };

    std::string sig{ values["signature"] };
    if (sig.size() >= 2 && sig.front() == '"' && sig.back() == '"') sig = sig.substr(1, sig.size() - 2);
    out.signature = sig;
    out.cls = values["class"];
    out.provider = values["provider"];
    out.catalog = values["catalogfile"];
    if (lower(sig) != "$windows nt$") problems.push_back("Signature must be $WINDOWS NT$");
    if (out.cls.empty()) problems.push_back("missing Class");
    if (out.provider.empty()) problems.push_back("missing Provider");
    if (out.catalog.empty()) problems.push_back("missing CatalogFile");
    if (!parseDriverVer(values["driverver"], out.ver)) problems.push_back("bad DriverVer");
    return problems;
}

int compareDriverVer(const DriverVer& a, const DriverVer& b)
{
    const int ka[]{ a.year, a.month, a.day, a.v[0], a.v[1], a.v[2], a.v[3] };
    const int kb[]{ b.year, b.month, b.day, b.v[0], b.v[1], b.v[2], b.v[3] };
    for (int i{ 0 }; i < 7; ++i) if (ka[i] != kb[i]) return ka[i] < kb[i] ? -1 : 1;
    return 0;
}

unitTests:
using Problems = std::vector<std::string>;
const std::string good =
    "; XenonLog.inf\r\n[Version]\r\nSignature   = \"$WINDOWS NT$\"\r\nClass       = System ; software driver\r\n"
    "ClassGuid   = {4d36e97d-e325-11ce-bfc1-08002be10318}\r\nprovider    = %ProviderName%\r\nDriverVer   = 11/15/2026,1.0.0.0\r\nCatalogFile = XenonLog.cat\r\n\r\n[Strings]\r\nClass = Other\r\n";
TEST("dates and versions") {
    DriverVer d{}; CHECK(parseDriverVer("11/15/2026,1.0.0.0", d)); CHECK_EQ(d.year, 2026); CHECK_EQ(d.v[0], 1);
    CHECK(parseDriverVer("2/29/2024,10.2", d)); CHECK_EQ(d.v[1], 2); CHECK_EQ(d.v[2], 0);
    CHECK(!parseDriverVer("2/29/2026,1.0", d)); CHECK(!parseDriverVer("13/01/2026,1.0", d)); CHECK(!parseDriverVer("11/15/2026", d)); CHECK(!parseDriverVer("11/15/2026,1.0.0.0.0", d));
    CHECK(!parseDriverVer("11/15/2026,70000.0", d)); CHECK(!parseDriverVer("11/15/2026, 1.0", d)); CHECK(!parseDriverVer("4/31/2026,1.0", d));
}
TEST("a good INF") {
    VersionInfo v{}; CHECK(checkVersion(good, v).empty()); CHECK_EQ(v.signature, std::string("$WINDOWS NT$")); CHECK_EQ(v.cls, std::string("System")); CHECK_EQ(v.catalog, std::string("XenonLog.cat")); CHECK_EQ(v.ver.day, 15);
}
TEST("problems") {
    VersionInfo v{};
    CHECK_EQ(checkVersion("[Strings]\nA = b\n", v), (Problems{ "no [Version] section" }));
    CHECK_EQ(checkVersion("[version]\nSignature = $Chicago$\nDriverVer = 1/1/2026,1\n", v), (Problems{ "Signature must be $WINDOWS NT$", "missing Class", "missing Provider", "missing CatalogFile" }));
    CHECK_EQ(checkVersion("[VERSION]\nsignature=$windows nt$\nClass=System\nProvider=Me\nCatalogFile=x.cat\n", v), (Problems{ "bad DriverVer" }));
}
TEST("which package wins") {
    DriverVer a{}, b{}, c{}; parseDriverVer("11/15/2026,1.0.0.0", a); parseDriverVer("11/15/2026,1.0.0.1", b); parseDriverVer("1/2/2027,0.1", c);
    CHECK_EQ(compareDriverVer(a, b), -1); CHECK_EQ(compareDriverVer(c, b), 1); CHECK_EQ(compareDriverVer(a, a), 0);
}

